Borg::Ship::Ship(int weaponFrequency, short repair)
{
    this->_maxWarp = 9;
    this->_maxWarp = 300;

    this->_weaponFrequency = weaponFrequency;
    this->_repair = repair;
    this->_shield = 100;

    std::cout << "We are the Borgs. Lower your shields and surrender yourselves unconditionally.\n";
