    int shield = target->getShield();

    if (this->_photonTorpedo - torpedoes >= 0) {
        this->_photonTorpedo -= torpedoes;
        std::cout << this->_name << ": Firing on target. " << this->_photonTorpedo << " torpedoes remaining.\n";
